static int get_eid_cmp(const void *s1, const void *s2)
{
    return nk_strcmp(*(char *const *) s1, *(char *const *) s2);
}
static kss_audit_operation_t _auditOperationToCBORValue(enum kss_audit_type t)
{
    switch (t) {
        
      case KSS_AUDIT_TYPE_REQUEST:
        return KSS_AUDIT_OPERATION_REQUEST;
        
      case KSS_AUDIT_TYPE_RESPONSE:
        return KSS_AUDIT_OPERATION_RESPONSE;
        
      case KSS_AUDIT_TYPE_EXECUTE:
        return KSS_AUDIT_OPERATION_EXECUTE;
        
      case KSS_AUDIT_TYPE_SECURITY:
        return KSS_AUDIT_OPERATION_SECURITY;
        
      default:
        return KSS_AUDIT_OPERATION_ERROR;
    }
}
static kss_slot_t currentSlotId = 0;
static nk_size_t cbor_audit_close(QCBOREncodeContext *ctx, UsefulBuf cbor_buf,
                                  kss_call_id call_id)
{
    QCBOREncode_CloseMap(ctx);
    QCBOREncode_CloseArray(ctx);
    // audit end
    QCBOREncode_CloseArray(ctx);
    
    UsefulBufC out_buf;
    QCBORError err = QCBOREncode_Finish(ctx, &out_buf);
    
    if (err != QCBOR_SUCCESS) {
        // reset out buffer
        QCBOREncode_Init(ctx, cbor_buf);
        // msg root
        QCBOREncode_AddTag(ctx, KSS_MESSAGE_TYPE_AUDIT);
        // audit array
        QCBOREncode_OpenArray(ctx);
        QCBOREncode_AddUInt64(ctx, call_id);
        QCBOREncode_AddTag(ctx, KSS_RESULT_FAILURE);
        QCBOREncode_AddUInt64(ctx, err);
        QCBOREncode_CloseArray(ctx);
        QCBOREncode_Finish(ctx, &out_buf);
    }
    return out_buf.len;
}
static void cbor_audit_open(QCBOREncodeContext *ctx, kss_call_id call_id, const
                            char *class_name, const char *object_name, const
                            char *method)
{
    // msg root
    QCBOREncode_AddTag(ctx, KSS_MESSAGE_TYPE_AUDIT);
    // audit array
    QCBOREncode_OpenArray(ctx);
    QCBOREncode_AddUInt64(ctx, call_id);
    QCBOREncode_AddTag(ctx, KSS_RESULT_SUCCESS);
    QCBOREncode_AddTag(ctx, KSS_AUDIT_SUBSYSTEM_PROVIDER);
    QCBOREncode_OpenArray(ctx);
    QCBOREncode_AddSZString(ctx, class_name);
    QCBOREncode_AddSZString(ctx, object_name);
    QCBOREncode_AddSZString(ctx, method);
    QCBOREncode_OpenMap(ctx);
}
