void __kss_fini(void)
{
    PSL_TRACE(CLS_KSS, "KSS", "Fini");
    currentSlotId = 0;
    PSL_TRACE(CLS_KSS, "KSS", "Fini done");
}
nk_err_t __kss_init(void)
{
    PSL_TRACE(CLS_KSS, "KSS", "Init");
    if (0 != currentSlotId) {
        PSL_TRACE(CLS_KSS_DENIED, "KSS",
                  "Warning: non-zero initial currentSlotId (%d)",
                  currentSlotId);
        currentSlotId = 0;
    }
    PSL_TRACE(CLS_KSS, "KSS", "Init done");
    return NK_EOK;
}
nk_err_t __kss_security(kss_decision_t *decision, kss_eid_t driver_eid,
                        nk_sid_t driver_sid, const struct nk_message *message,
                        const struct nk_arena *arena,
                        struct kss_audit_message *audit_message)
{
    nk_err_t rc = NK_ENOENT;
    
    nk_unused(decision);
    nk_unused(driver_sid);
    nk_unused(arena);
    PSL_TRACE(CLS_PSL, "PSL", "driver: %d", driver_eid);
    switch (driver_eid) {
        
      default:
        break;
    }
    switch (rc) {
        
      case NK_EINVAL:
        {
            kss_call_id psl_call_id = kss_alloc_call_id();
            nk_uint8_t auditBuf[2048];
            nk_size_t auditBufWritten = emit_audit_CBOR(auditBuf, 2048,
                                                        psl_call_id,
                                                        _auditOperationToCBORValue(audit_message->type),
                                                        __kss_get_eiid(audit_message->src_eid),
                                                        audit_message->src_eid,
                                                        __kss_get_eiid(audit_message->dst_eid),
                                                        audit_message->dst_eid,
                                                        security_method(driver_eid,
                                                                        message->iid,
                                                                        message->mid),
                                                        audit_message->mid,
                                                        audit_message->iid,
                                                        KSS_AUDIT_SUBSYSTEM_VALIDATOR,
                                                        KSS_DENY);
            
            {
                kss_audit_header header = {.callId =psl_call_id, .tag =
                                           KSS_AUDIT_MESSAGE_FORMAT_CBOR,
                                           .size =
                                           (nk_uint16_t) auditBufWritten};
                
                AUDIT_LOG_TO_CORE_DEBUG_CONSOLE(header, auditBuf);
                kss_audit_log(&header, sizeof(header), auditBuf, header.size);
            }
            ;
            return rc;
        }
        
      case NK_ENOENT:
        {
            kss_call_id psl_call_id = kss_alloc_call_id();
            nk_uint8_t auditBuf[2048];
            nk_size_t auditBufWritten = emit_audit_CBOR(auditBuf, 2048,
                                                        psl_call_id,
                                                        _auditOperationToCBORValue(audit_message->type),
                                                        __kss_get_eiid(audit_message->src_eid),
                                                        audit_message->src_eid,
                                                        __kss_get_eiid(audit_message->dst_eid),
                                                        audit_message->dst_eid,
                                                        security_method(driver_eid,
                                                                        message->iid,
                                                                        message->mid),
                                                        audit_message->mid,
                                                        audit_message->iid,
                                                        KSS_AUDIT_SUBSYSTEM_ROUTER,
                                                        KSS_DENY);
            
            {
                kss_audit_header header = {.callId =psl_call_id, .tag =
                                           KSS_AUDIT_MESSAGE_FORMAT_CBOR,
                                           .size =
                                           (nk_uint16_t) auditBufWritten};
                
                AUDIT_LOG_TO_CORE_DEBUG_CONSOLE(header, auditBuf);
                kss_audit_log(&header, sizeof(header), auditBuf, header.size);
            }
            ;
            return rc;
        }
        
      default:
        return rc;
    }
    ;
}
static void audit_epilogue(const kss_call_id call_id, const
                           struct kss_audit_message *message, const
                           kss_decision_t *decision)
{
    nk_assert(message != NK_NULL);
    PSL_TRACE(CLS_KSS, "Audit",
              "call=%u decision=%u type=%u eids=%u:%u sids=%u:%u method=%u.%u",
              (unsigned int) call_id, (unsigned int) *decision,
              (unsigned int) message->type, (unsigned int) message->src_eid,
              (unsigned int) message->dst_eid, (unsigned int) message->src_sid,
              (unsigned int) message->dst_sid, (unsigned int) message->iid,
              (unsigned int) message->mid);
    
    kss_eid_t src_eid = message->src_eid;
    const char *src_name = __kss_get_eiid(src_eid);
    kss_eid_t dst_eid = KSS_INVALID_EID;
    const char *dst_name = "NULL";
    
    if (message->type != KSS_AUDIT_TYPE_SECURITY) {
        dst_eid = message->dst_eid;
        dst_name = __kss_get_eiid(dst_eid);
    }
    
    const char *method_name = "NULL";
    
    switch (message->type) {
        
      case KSS_AUDIT_TYPE_EXECUTE:
        method_name = execute_method(message->mid);
        break;
        
      case KSS_AUDIT_TYPE_REQUEST:
        method_name = endpoint_method(dst_eid, message->iid, message->mid);
        break;
        
      case KSS_AUDIT_TYPE_RESPONSE:
        method_name = endpoint_method(src_eid, message->iid, message->mid);
        break;
        
      case KSS_AUDIT_TYPE_SECURITY:
        method_name = security_method(src_eid, message->iid, message->mid);
        break;
        
      default:
        nk_assert(0);
        return;
    }
    
    nk_uint8_t audit_buf[2048];
    nk_size_t audit_buf_written = emit_audit_CBOR(audit_buf, 2048, call_id,
                                                  _auditOperationToCBORValue(message->type),
                                                  src_name, src_eid, dst_name,
                                                  dst_eid, method_name,
                                                  message->mid, message->iid,
                                                  KSS_AUDIT_SUBSYSTEM_EPILOGUE,
                                                  *decision);
    kss_audit_header header = {.callId =call_id, .tag =
                               KSS_AUDIT_MESSAGE_FORMAT_CBOR, .size =
                               (nk_uint16_t) audit_buf_written};
    
    AUDIT_LOG_TO_CORE_DEBUG_CONSOLE(header, audit_buf);
    kss_audit_log(&header, sizeof(header), audit_buf, header.size);
}
